INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('2988c988-44af-4744-bbf5-031bcccf7926', 'c3c3c3c3-3030-4000-8000-000000000003', 5, 'Dia 5 — Pensamentos', 'Semana 1: Parar', '{"pch": "Pensai em tudo o que \u00e9 verdadeiro, nobre, justo\u2026 Voc\u00ea \u00e9 o que pensa repetidamente.", "verse": "Fl 4,8", "lectio": "Leia Fl 4,4-9. A receita da paz.", "practice": "Observe seus pensamentos por 10 min sem reagir. Apenas note.", "question": "Quais pensamentos se repetem na sua mente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;